// Focus sounds, generated by the app (no audio files, CC0 by construction), endless and gap-free:
// - Noise (white / pink / brown) and textures (rain, ocean, wind, fireplace) come from an AudioWorklet that makes
//   new samples forever, so there is no loop point at all.
// - Where AudioWorklet is missing, a 30 s buffer is used whose end is crossfaded into its start (equal power), and it
//   plays with AudioBufferSourceNode.loop = true: no gap and no click at the seam. Any future recorded loop goes through
//   the same seamlessLoop() helper. (<audio loop> is never used: it leaves a gap.)
// - The graph is also routed to a MediaStream <audio> element and a Media Session, so mobile browsers treat it as
//   media playback and keep it going with the screen off; a watchdog resumes the AudioContext if the OS suspends it.
export const SOUNDS = [['off', 'Off'], ['rain', 'Rain'], ['ocean', 'Ocean'], ['wind', 'Wind'], ['fire', 'Fireplace'], ['brown', 'Brown noise'], ['pink', 'Pink noise'], ['white', 'White noise']];
const Ctx = () => globalThis.AudioContext || globalThis.webkitAudioContext;
export const soundSupported = () => !!Ctx();

// ---- sample generators (pure, shared by the worklet source and the buffer fallback) ----
export function makeGen(kind, sampleRate = 48000, seed = 1) {
  let s = seed >>> 0 || 1; const rnd = () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return ((s >>> 0) / 4294967296) * 2 - 1; };
  let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0, brown = 0, lp = 0, lp2 = 0, t = 0, crackle = 0, env = 0, drop = 0;
  const pink = w => { b0 = 0.99886 * b0 + w * 0.0555179; b1 = 0.99332 * b1 + w * 0.0750759; b2 = 0.969 * b2 + w * 0.153852; b3 = 0.8665 * b3 + w * 0.3104856; b4 = 0.55 * b4 + w * 0.5329522; b5 = -0.7616 * b5 - w * 0.016898; const o = b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362; b6 = w * 0.115926; return o * 0.11; };
  const br = w => { brown = (brown + 0.02 * w) / 1.02; return brown * 3.5; };
  const dt = 1 / sampleRate;
  return () => {
    const w = rnd(); t += dt;
    switch (kind) {
      case 'white': return w * 0.3;
      case 'pink': return pink(w);
      case 'brown': return br(w);
      case 'rain': { const p = pink(w); lp += 0.25 * (p - lp); if (drop <= 0 && rnd() > 0.9993) drop = 1; drop *= 0.985; return lp * 0.9 + w * drop * 0.25; }
      case 'ocean': { const sw = 0.55 + 0.45 * Math.sin(2 * Math.PI * t / 9) * Math.sin(2 * Math.PI * t / 23 + 1); lp += 0.06 * (br(w) - lp); return lp * Math.max(0.12, sw) * 1.6; }
      case 'wind': { const g = 0.5 + 0.5 * Math.sin(2 * Math.PI * t / 13 + Math.sin(t / 3)); lp += (0.01 + 0.05 * g) * (pink(w) - lp); return lp * 2.4 * (0.4 + 0.6 * g); }
      case 'fire': { lp2 += 0.03 * (br(w) - lp2); if (rnd() > 0.9996) crackle = 1; crackle *= 0.93; env = crackle * w; return lp2 * 0.8 + env * 0.5; }
      default: return 0;
    }
  };
}
// Equal-power crossfade of the buffer's tail into its head, so buffer.loop = true is seamless.
export function seamlessLoop(data, fade) {
  const n = data.length - fade, out = new Float32Array(n);
  out.set(data.subarray(0, n));
  for (let i = 0; i < fade; i++) { const x = i / fade, a = Math.cos(x * Math.PI / 2), b = Math.sin(x * Math.PI / 2); out[i] = data[n + i] * a + data[i] * b; }
  return out;
}
// Largest gap in a rendered signal: longest run (seconds) of windows quieter than threshold; plus seam jump size.
export function silenceStats(data, sampleRate, { win = 0.05, threshold = 0.002 } = {}) {
  const w = Math.max(1, Math.round(win * sampleRate)); let run = 0, longest = 0, minRms = Infinity;
  for (let i = 0; i + w <= data.length; i += w) { let e = 0; for (let k = i; k < i + w; k++) e += data[k] * data[k]; const rms = Math.sqrt(e / w); minRms = Math.min(minRms, rms); if (rms < threshold) { run += win; longest = Math.max(longest, run); } else run = 0; }
  return { longestSilence: longest, minRms };
}

const WORKLET = `const makeGen = ${makeGen.toString()};
class Noise extends AudioWorkletProcessor { constructor(o) { super(); this.g = makeGen(o.processorOptions.kind, sampleRate, o.processorOptions.seed); this.g2 = makeGen(o.processorOptions.kind, sampleRate, o.processorOptions.seed + 7); }
  process(_, outs) { const o = outs[0]; const L = o[0], R = o[1] || o[0]; for (let i = 0; i < L.length; i++) { L[i] = this.g(); if (R !== L) R[i] = this.g2(); } return true; } }
registerProcessor('ka-noise', Noise);`;
// Builds the sound graph in any (online or offline) context. Returns { output, start, stop }.
export async function buildSound(c, kind, { useWorklet = true } = {}) {
  const out = c.createGain();
  if (useWorklet && c.audioWorklet && typeof AudioWorkletNode !== 'undefined') {
    try {
      if (!c.__kaWorklet) { const url = URL.createObjectURL(new Blob([WORKLET], { type: 'text/javascript' })); c.__kaWorklet = c.audioWorklet.addModule(url); }
      await c.__kaWorklet;
      const n = new AudioWorkletNode(c, 'ka-noise', { numberOfInputs: 0, outputChannelCount: [2], processorOptions: { kind, seed: 12345 } });
      n.connect(out); return { output: out, start() {}, stop() { n.disconnect(); }, mode: 'worklet' };
    } catch (e) { globalThis.__kaWorkletError = String(e?.message || e); /* fall back to a buffer */ }
  }
  const sr = c.sampleRate, fade = Math.round(sr * 1.5), len = sr * 30 + fade, buf = c.createBuffer(2, len - fade, sr);
  for (let ch = 0; ch < 2; ch++) { const g = makeGen(kind, sr, 12345 + ch * 7), d = new Float32Array(len); for (let i = 0; i < len; i++) d[i] = g(); buf.copyToChannel(seamlessLoop(d, fade), ch); }
  const src = c.createBufferSource(); src.buffer = buf; src.loop = true; src.connect(out);
  return { output: out, start(t = 0) { src.start(t); }, stop() { try { src.stop(); } catch { /* done */ } }, mode: 'buffer' };
}

// ---- live player ----
let ctx = null, cur = null, master = null, mediaEl = null, watchdog = null, wanted = null, sleepTimer = null;
function context() { if (!ctx) { const C = Ctx(); if (!C) return null; ctx = new C({ latencyHint: 'playback' }); ctx.addEventListener?.('statechange', () => { if (wanted && ctx.state !== 'running') ctx.resume().catch(() => {}); }); } if (ctx.state !== 'running') ctx.resume().catch(() => {}); return ctx; }
function keepAlive(c) {
  // A MediaStream <audio> makes the OS treat this as media playback (background / screen off), with a Media Session.
  try {
    if (!mediaEl && c.createMediaStreamDestination) { const dest = c.createMediaStreamDestination(); master.connect(dest); mediaEl = new Audio(); mediaEl.srcObject = dest.stream; mediaEl.muted = false; mediaEl.volume = 0.0001; }
    mediaEl?.play().catch(() => {});
    if ('mediaSession' in navigator) { navigator.mediaSession.metadata = new MediaMetadata({ title: SOUNDS.find(s => s[0] === wanted?.kind)?.[1] || 'Focus sound', artist: 'Prvlar · Focus' }); navigator.mediaSession.playbackState = 'playing'; navigator.mediaSession.setActionHandler('pause', () => stopAmbient()); }
  } catch { /* optional */ }
  globalThis.Capacitor?.Plugins?.AtlasMedia?.setBackgroundAudio({ on: true }).catch?.(() => {});
  clearInterval(watchdog);
  watchdog = setInterval(() => { if (!wanted) return; if (ctx.state !== 'running') ctx.resume().catch(() => {}); if (mediaEl?.paused) mediaEl.play().catch(() => {}); }, 4000);
}
export async function playAmbient(kind, volume = 0.5, { sleepMin = 0, useWorklet = true } = {}) {
  stopAmbient();
  if (!kind || kind === 'off') return false;
  const c = context(); if (!c) return false;
  wanted = { kind, volume };
  if (!master) { master = c.createGain(); master.connect(c.destination); }
  master.gain.cancelScheduledValues(c.currentTime); master.gain.setValueAtTime(0, c.currentTime);
  const s = await buildSound(c, kind, { useWorklet }); if (wanted?.kind !== kind) { s.stop(); return false; }
  s.output.connect(master); s.start(); cur = s;
  master.gain.setTargetAtTime(Math.max(0, Math.min(1, volume)) * 0.6, c.currentTime, 0.4);   // fade in
  keepAlive(c);
  clearTimeout(sleepTimer); if (sleepMin > 0) sleepTimer = setTimeout(() => stopAmbient(true), sleepMin * 60000);
  return true;
}
export function setAmbientVolume(v) { if (wanted) wanted.volume = v; if (master && ctx) master.gain.setTargetAtTime(Math.max(0, Math.min(1, v)) * 0.6, ctx.currentTime, 0.1); }
export function stopAmbient(fade = false) {
  wanted = null; clearInterval(watchdog); clearTimeout(sleepTimer);
  const s = cur; cur = null;
  if (s && fade && ctx && master) { master.gain.setTargetAtTime(0, ctx.currentTime, 0.6); setTimeout(() => s.stop(), 3000); } else s?.stop();
  try { mediaEl?.pause(); if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'none'; } catch { /* ignore */ }
  globalThis.Capacitor?.Plugins?.AtlasMedia?.setBackgroundAudio({ on: false }).catch?.(() => {});
}
export const ambientPlaying = () => !!cur;
export const ambientMode = () => cur?.mode || '';
export const ambientTap = () => master;   // for the long-play test

// Three soft notes (or two, lower, for the end of a break).
export function chime(up = true) {
  const c = context(); if (!c) return;
  const notes = up ? [660, 880, 1320] : [880, 660];
  notes.forEach((f, i) => {
    const o = c.createOscillator(), g = c.createGain(), t = c.currentTime + i * 0.22;
    o.type = 'sine'; o.frequency.value = f;
    g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.25, t + 0.02); g.gain.exponentialRampToValueAtTime(0.001, t + 0.9);
    o.connect(g); g.connect(c.destination); o.start(t); o.stop(t + 1);
  });
}
